import moe.cangku.reader.*;
import java.util.*;
public class RichEditorDocumentTest {
 static int n;static void ok(boolean b){if(!b)throw new AssertionError("rich editor check "+(n+1));n++;}
 public static void main(String[] args){
  String html="<p>Hello <strong>星屿</strong> &amp; 朋友<img src='https://example.com/one.webp' alt='图'></p>\n[dlbox title=\"下载\" link1=\"a|https://example.com/file\"][/dlbox]";
  RichEditorDocument d=new RichEditorDocument(html);ok(d.source.equals(html));ok(!d.text.contains("<strong>"));ok(d.text.contains("星屿 & 朋友"));ok(d.units.stream().filter(u->u.kind.equals("image")).count()==1);ok(d.units.stream().filter(u->u.kind.equals("dlbox")).count()==1);ok(d.marks.stream().anyMatch(m->m.tag.equals("strong")&&d.text.substring(m.a,m.b).equals("星屿")));
  int a=d.text.indexOf("星屿");String changed=d.replace(a,a+2,"星海 <测试>");ok(changed.contains("<strong>星海 &lt;测试&gt;</strong>"));ok(changed.contains("<img src='https://example.com/one.webp' alt='图'>"));ok(changed.contains("[dlbox title=\"下载\""));
  RichEditorDocument twice=new RichEditorDocument(new RichEditorDocument(changed).source);ok(twice.source.equals(changed));ok(twice.text.contains("星海 <测试>"));
  int image=d.text.indexOf('\uFFFC');String deleted=d.replace(image,image+1,"");ok(!deleted.contains("<img"));ok(deleted.contains("[dlbox"));
  RichEditorDocument encoded=new RichEditorDocument("<p>A &amp; B</p>");ok(encoded.replace(2,3,"&").equals("<p>A &amp; B</p>"));ok(encoded.sourceOffset(1,true)==4);ok(encoded.sourceOffset(5,true)==12);
  RichEditorDocument wrapped=new RichEditorDocument("<p><strong>hello</strong></p>");ok(wrapped.source.substring(wrapped.sourceOffset(0),wrapped.sourceOffset(5,true)).equals("hello"));ok(wrapped.replace(0,5,"new").equals("<p><strong>new</strong></p>"));
  RichEditorDocument caret=new RichEditorDocument("<p>a</p>");ok(caret.replace(1,1,"b").equals("<p>ab</p>"));RichEditorDocument paragraphs=new RichEditorDocument("<p>A</p><p>B</p>");ok(paragraphs.replace(1,2,"").equals("<p>AB</p>"));
  RichEditorDocument cross=new RichEditorDocument("<p>A</p>\n<p>B</p>");ok(cross.text.equals("A\nB"));ok(cross.wrapVisible(0,3,"<strong>","</strong>").equals("<p><strong>A</strong></p>\n<p><strong>B</strong></p>"));
  RichEditorDocument ime=new RichEditorDocument("<p>中文😀</p>");ok(ime.replace(0,2,"你好").equals("<p>你好😀</p>"));ok(ime.replace(2,4,"😁").equals("<p>中文😁</p>"));ok(ime.replace(4,4,"后续").equals("<p>中文😀后续</p>"));ok(new RichEditorDocument("<p>A<br>B</p>").replace(1,2,"").equals("<p>AB</p>"));RichEditorDocument lastImage=new RichEditorDocument("<p><img src='https://example.com/x.png'></p>");ok(lastImage.replace(1,1,"之后").contains("<img src='https://example.com/x.png'>之后</p>"));
  RichEditorDocument splitting=new RichEditorDocument("<p><strong>AB</strong></p>");String split=splitting.insertMarkup(1,1,"<p><img src='https://example.com/a'></p>");ok(split.equals("<p><strong>A</strong></p><p><img src='https://example.com/a'></p><p><strong>B</strong></p>"));ok(new RichEditorDocument("<p>中文</p>").text.equals("中文"));ok(new RichEditorDocument("[poll]11[/poll]").text.equals("\uFFFC"));
  ok(RichEditorDocument.withinCapacity("a".repeat(1000000)));ok(!RichEditorDocument.withinCapacity("a".repeat(1000001)));RichEditorDocument escapedLarge=new RichEditorDocument("<p>"+"a".repeat(999990)+"</p>");String proposed=escapedLarge.replace(0,0,"<<<");ok(!RichEditorDocument.withinCapacity(proposed));ok(escapedLarge.source.length()==999997);
  ok(NativePrintPagination.count(0,700)==1);ok(NativePrintPagination.count(701,700)==2);ok(NativePrintPagination.count(700,700)==1);ok(NativePrintPagination.included(3,new int[][]{{0,1},{3,4}}));ok(!NativePrintPagination.included(2,new int[][]{{0,1},{3,4}}));try{NativePrintPagination.count(351000,700);throw new AssertionError("oversize print accepted");}catch(IllegalArgumentException expected){n++;}
  RichEditorDocument table=new RichEditorDocument("<p>before</p><table><tr><td>cell</td></tr></table><p>after</p>");int[] tableRange=table.enclosing("table",table.source.indexOf("cell"));ok(tableRange!=null&&table.source.substring(tableRange[0],tableRange[1]).equals("<table><tr><td>cell</td></tr></table>"));ok(table.enclosing("table",0)==null);
  String card=EditorTemplates.download("标题","今天","官网","123","abc",Arrays.asList(new EditorTemplates.Link("GitHub","https://example.com/a"),new EditorTemplates.Link("备用","https://example.com/b")));ok(card.contains("time=\"今天\""));ok(card.contains("from=\"官网\""));ok(card.contains("提取：123 / 密码：abc"));ok(card.contains("link2=\"备用|https://example.com/b\""));ok(EditorTemplates.external("https://example.com/video").equals("[iframe]https://example.com/video[/iframe]"));ok(EditorTemplates.EXTERNAL_SERVICES.length==21);ok(EditorTemplates.rapid("中文",false).endsWith("5Lit5paH"));
  EditorTemplates.Download parsed=EditorTemplates.parseDownload(card);ok(parsed.title.equals("标题"));ok(parsed.time.equals("今天")&&parsed.from.equals("官网"));ok(parsed.extraction.equals("123")&&parsed.password.equals("abc"));ok(parsed.links.size()==2&&parsed.links.get(1).name.equals("备用"));String unchanged=EditorTemplates.updateDownload(parsed,parsed.title,parsed.time,parsed.from,parsed.extraction,parsed.password,parsed.otherInfo,parsed.links);ok(unchanged.equals(card));EditorTemplates.Download legacy=EditorTemplates.parseDownload("[dlbox title='旧标题' info='3GB &amp; 校验信息' custom='保留' link7='主站|https://example.com/1' link12='备用|https://example.com/2']原有组件附注[/dlbox]");ok(legacy.otherInfo.equals("3GB & 校验信息"));ok(legacy.links.size()==2);String updated=EditorTemplates.updateDownload(legacy,"新标题","","","","",legacy.otherInfo,legacy.links);ok(updated.contains("custom=\"保留\""));ok(updated.contains("info=\"3GB &amp; 校验信息\""));ok(updated.endsWith("]原有组件附注[/dlbox]"));EditorTemplates.Download oldParsed=EditorTemplates.parseDownload(updated);ok(oldParsed.otherInfo.equals(legacy.otherInfo)&&oldParsed.links.size()==2);
  try{EditorTemplates.download("x","","","","",Arrays.asList(new EditorTemplates.Link("x","javascript:alert(1)")));throw new AssertionError("unsafe accepted");}catch(IllegalArgumentException expected){n++;}
  try{EditorTemplates.external("https://example.com/[/iframe]");throw new AssertionError("shortcode injection accepted");}catch(IllegalArgumentException expected){n++;}
  RichEditorDocument literalCode=new RichEditorDocument("<pre><code>[dlbox title=\"example\"][/dlbox]</code></pre>");ok(literalCode.text.contains("[dlbox"));ok(!literalCode.text.contains("\uFFFC"));ok(literalCode.source.equals("<pre><code>[dlbox title=\"example\"][/dlbox]</code></pre>"));
   String linked="<p>前 <a class='keep' target='_blank' href='https://example.com/a?a=1&amp;b=2'><strong>原始 &amp; 链接</strong></a> 后</p>";
   RichEditorDocument links=new RichEditorDocument(linked);int cursor=links.text.indexOf("原始")+1;RichEditorDocument.Link link=links.linkAt(cursor,cursor);
   ok(link!=null&&link.url.equals("https://example.com/a?a=1&b=2"));ok(link.label.equals("原始 & 链接"));
   String newUrl=links.updateLink(link,link.label,"https://example.com/new?a=3&b=4",false);ok(newUrl.contains("<strong>原始 &amp; 链接</strong>"));ok(newUrl.contains("class='keep' target='_blank'"));ok(newUrl.contains("href=\"https://example.com/new?a=3&amp;b=4\""));ok(new RichEditorDocument(newUrl).text.equals(links.text));
   String renamed=links.updateLink(link,"新 <名字>",link.url,false);ok(renamed.contains(">新 &lt;名字&gt;</a>"));ok(renamed.startsWith("<p>前 ")&&renamed.endsWith(" 后</p>"));
   ok(links.updateLink(link,link.label,link.url,true).equals("<p>前 <strong>原始 &amp; 链接</strong> 后</p>"));
   ok(links.linkAt(0,1)==null);ok(links.linkAt(cursor,links.text.length())==null);ok(links.linkAt(cursor,cursor+2)!=null);
   ok(new RichEditorDocument("<pre><code>&lt;a href='x'&gt;例子&lt;/a&gt;</code></pre>").linkAt(1,1)==null);
   ok(new RichEditorDocument("<a href='https://example.com'><img src='https://example.com/x.png'></a>").linkAt(0,0)==null);
  System.out.println("PASS "+n+" native visual source, image, formatting, entity and website template checks");
 }
}
